/* From Uiverse.io by Juanes200122  - Tags: icon, animation, social, twitter, facebook, instagram, button, hover */
.__UIV_SCOPE__ ul {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  margin: 0;
  padding: 0;
  display: flex;
}
.__UIV_SCOPE__ ul li {
  list-style: none;
}
.__UIV_SCOPE__ ul li a {
  display: block;
  position: relative;
  width: 100px;
  height: 100px;
  line-height: 100px;
  font-size: 40px;
  text-align: center;
  text-decoration: none;
  color: #404040;
  margin: 0 30px;
  transition: 0.5s;
}
.__UIV_SCOPE__ ul li a span {
  position: absolute;
  transition: transform 0.5s;
}
.__UIV_SCOPE__ ul li a span:nth-child(1),
.__UIV_SCOPE__ ul li a span:nth-child(3) {
  width: 100%;
  height: 3px;
  background: #404040;
}
.__UIV_SCOPE__ ul li a span:nth-child(1) {
  top: 0;
  left: 0;
  transform-origin: right;
}
.__UIV_SCOPE__ ul li a:hover span:nth-child(1) {
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.5s;
}

.__UIV_SCOPE__ ul li a span:nth-child(3) {
  bottom: 0;
  left: 0;
  transform-origin: left;
}
.__UIV_SCOPE__ ul li a:hover span:nth-child(3) {
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 0.5s;
}

.__UIV_SCOPE__ ul li a span:nth-child(2),
.__UIV_SCOPE__ ul li a span:nth-child(4) {
  width: 3px;
  height: 100%;
  background: #404040;
}
.__UIV_SCOPE__ ul li a span:nth-child(2) {
  top: 0;
  left: 0;
  transform: scale(0);
  transform-origin: bottom;
}
.__UIV_SCOPE__ ul li a:hover span:nth-child(2) {
  transform: scale(1);
  transform-origin: top;
  transition: transform 0.5s;
}
.__UIV_SCOPE__ ul li a span:nth-child(4) {
  top: 0;
  right: 0;
  transform: scale(0);
  transform-origin: top;
}
.__UIV_SCOPE__ ul li a:hover span:nth-child(4) {
  transform: scale(1);
  transform-origin: bottom;
  transition: transform 0.5s;
}

.__UIV_SCOPE__ .facebook:hover {
  color: #3b5998;
}
.__UIV_SCOPE__ .facebook:hover span {
  background: #3b5998;
}
